import { motion } from 'framer-motion';
import { BarChart3, Menu, Settings, Volume2, VolumeX, Wallet } from 'lucide-react';
import { useCasino } from '../context/CasinoContext';

const Header = () => {
  const { state, setModal, toggleSidebar, updateSettings } = useCasino();
  const { balance, settings, sidebarOpen } = state;

  const toggleSound = () => {
    updateSettings({ soundEnabled: !settings.soundEnabled });
  };

  return (
    <header className="h-16 bg-casino-card border-b border-casino-border flex items-center justify-between px-4 shrink-0">
      {/* Left - Menu toggle */}
      <div className="flex items-center gap-4">
        <button onClick={toggleSidebar} className="lg:hidden p-2 hover:bg-casino-border rounded-lg transition text-gray-400 hover:text-white">
          <Menu className="w-6 h-6" />
        </button>

        <div className="hidden sm:flex items-center gap-2 text-sm text-gray-500">
          <span className="font-medium text-white">Welcome to</span>
          <span className="font-black text-casino-cyan">CASINO</span>
        </div>
      </div>

      {/* Right - Controls */}
      <div className="flex items-center gap-3">
        {/* Balance */}
        <motion.div
          className="flex items-center gap-2 bg-casino-bg px-4 py-2 rounded-xl border border-casino-border"
          whileHover={{ scale: 1.02 }}
          initial={{ opacity: 0, y: -10 }}
          animate={{ opacity: 1, y: 0 }}
        >
          <Wallet className="w-5 h-5 text-casino-green" />
          <span className="font-black text-lg">
            <span className="text-gray-500 text-sm mr-1">$</span>
            <span className="text-white">{balance.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</span>
          </span>
        </motion.div>

        {/* Sound Toggle */}
        <motion.button
          onClick={toggleSound}
          className={`p-2.5 rounded-xl border transition ${settings.soundEnabled ? 'bg-casino-cyan/10 border-casino-cyan text-casino-cyan' : 'bg-casino-bg border-casino-border text-gray-500 hover:text-white'}`}
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
        >
          {settings.soundEnabled ? <Volume2 className="w-5 h-5" /> : <VolumeX className="w-5 h-5" />}
        </motion.button>

        {/* Stats Button */}
        <motion.button
          onClick={() => setModal('stats')}
          className="p-2.5 rounded-xl bg-casino-bg border border-casino-border text-gray-400 hover:text-white hover:border-casino-gold transition"
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
        >
          <BarChart3 className="w-5 h-5" />
        </motion.button>

        {/* Settings Button */}
        <motion.button
          onClick={() => setModal('settings')}
          className="p-2.5 rounded-xl bg-casino-bg border border-casino-border text-gray-400 hover:text-white hover:border-casino-cyan transition"
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
        >
          <Settings className="w-5 h-5" />
        </motion.button>
      </div>
    </header>
  );
};

export default Header;
