import { AnimatePresence, motion } from 'framer-motion';
import {
    Activity,
    ChevronLeft,
    ChevronRight,
    Circle,
    Dices,
    Flame,
    Gem,
    Grid3X3,
    Home,
    Layers,
    Sparkles,
    Target,
    TrendingUp,
    Trophy,
    Zap
} from 'lucide-react';
import { useCasino } from '../context/CasinoContext';

const games = [
  { id: 'crash', name: 'Crash', icon: TrendingUp, color: 'from-casino-red to-orange-600' },
  { id: 'mines', name: 'Mines', icon: Grid3X3, color: 'from-casino-green to-emerald-600' },
  { id: 'dice', name: 'Dice', icon: Dices, color: 'from-casino-cyan to-blue-600' },
  { id: 'plinko', name: 'Plinko', icon: Activity, color: 'from-casino-gold to-yellow-600' },
  { id: 'limbo', name: 'Limbo', icon: Zap, color: 'from-purple-500 to-violet-600' },
  { id: 'roulette', name: 'Roulette', icon: Target, color: 'from-casino-red to-pink-600' },
  { id: 'blackjack', name: 'Blackjack', icon: Layers, color: 'from-gray-600 to-gray-800' },
  { id: 'coinflip', name: 'Coin Flip', icon: Circle, color: 'from-casino-gold to-amber-600' },
  { id: 'tower', name: 'Tower', icon: Trophy, color: 'from-indigo-500 to-blue-600' },
  { id: 'keno', name: 'Keno', icon: Sparkles, color: 'from-pink-500 to-rose-600' },
  { id: 'slots', name: 'Lucky Slots', icon: Gem, color: 'from-casino-cyan to-teal-600' }
];

const Sidebar = () => {
  const { state, setCurrentGame, toggleSidebar } = useCasino();
  const { currentGame, sidebarOpen, hotGames } = state;

  // Use hotGames from state, with fallback
  const hotGamesList = hotGames && hotGames.length > 0 ? hotGames : ['crash', 'mines', 'plinko', 'roulette'];

  return (
    <>
      {/* Mobile overlay */}
      <AnimatePresence>
        {sidebarOpen && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 bg-black/50 z-30 lg:hidden" onClick={toggleSidebar} />
        )}
      </AnimatePresence>

      {/* Sidebar */}
      <motion.aside
        initial={false}
        animate={{
          width: sidebarOpen ? 240 : 60,
          x: 0
        }}
        className={`
          fixed lg:relative inset-y-0 left-0 z-40
          bg-casino-card border-r border-casino-border
          flex flex-col h-full overflow-hidden
          ${!sidebarOpen ? '-translate-x-full lg:translate-x-0' : ''}
        `}
      >
        {/* Logo / Header */}
        <div className="h-16 flex items-center justify-between px-3 shrink-0">
          <AnimatePresence mode="wait">
            {sidebarOpen && (
              <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="flex items-center gap-2">
                <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-casino-cyan to-casino-green flex items-center justify-center">
                  <Gem className="w-5 h-5 text-casino-bg" />
                </div>
                <span className="font-black text-lg tracking-tight">
                  <span className="text-casino-cyan">CASINO</span>
                </span>
              </motion.div>
            )}
          </AnimatePresence>

          <button onClick={toggleSidebar} className="p-2 hover:bg-casino-border rounded-lg transition text-gray-400 hover:text-white">
            {sidebarOpen ? <ChevronLeft className="w-5 h-5" /> : <ChevronRight className="w-5 h-5" />}
          </button>
        </div>

        {/* Games List */}
        <nav className="flex-1 overflow-y-auto py-4 px-2">
          {/* Dashboard button */}
          <motion.button
            onClick={() => setCurrentGame(null)}
            className={`
              w-full flex items-center gap-3 px-3 py-2.5 rounded-xl mb-3 transition-all
              ${currentGame === null ? 'bg-casino-cyan text-casino-bg' : 'text-gray-400 hover:text-white hover:bg-casino-border'}
            `}
            whileHover={{ x: 4 }}
            whileTap={{ scale: 0.98 }}
          >
            <div className={`w-8 h-8 rounded-lg flex items-center justify-center shrink-0 ${currentGame === null ? 'bg-white/20' : 'bg-casino-border'}`}>
              <Home className="w-5 h-5" />
            </div>
            <AnimatePresence mode="wait">
              {sidebarOpen && (
                <motion.span initial={{ opacity: 0, x: -10 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -10 }} className="font-semibold text-sm">
                  Dashboard
                </motion.span>
              )}
            </AnimatePresence>
          </motion.button>

          <AnimatePresence mode="wait">
            {sidebarOpen && (
              <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="text-xs font-bold text-gray-500 uppercase tracking-wider px-3 mb-3">
                Casino Games
              </motion.div>
            )}
          </AnimatePresence>

          <div className="space-y-1">
            {games.map((game) => {
              const Icon = game.icon;
              const isActive = currentGame === game.id;
              const isHot = hotGamesList.includes(game.id);

              return (
                <motion.button
                  key={game.id}
                  onClick={() => setCurrentGame(game.id)}
                  className={`
                    w-full flex items-center gap-3 px-3 py-2.5 rounded-xl transition-all
                    ${isActive ? `bg-gradient-to-r ${game.color} text-white shadow-lg` : 'text-gray-400 hover:text-white hover:bg-casino-border'}
                  `}
                  whileHover={{ x: 4 }}
                  whileTap={{ scale: 0.98 }}
                >
                  <div className={`w-8 h-8 rounded-lg flex items-center justify-center shrink-0 ${isActive ? 'bg-white/20' : 'bg-casino-border'}`}>
                    <Icon className={`w-5 h-5 ${isActive ? 'text-white' : ''}`} />
                  </div>

                  <AnimatePresence mode="wait">
                    {sidebarOpen && (
                      <motion.div initial={{ opacity: 0, x: -10 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -10 }} className="flex-1 flex items-center justify-between overflow-hidden">
                        <span className="font-semibold text-sm truncate">{game.name}</span>

                        {isHot && (
                          <motion.div
                            initial={{ scale: 0 }}
                            animate={{ scale: 1 }}
                            className="flex items-center gap-1 bg-casino-red/20 text-casino-red px-1.5 py-0.5 rounded text-[10px] font-bold"
                          >
                            <Flame className="w-3 h-3" />
                            HOT
                          </motion.div>
                        )}
                      </motion.div>
                    )}
                  </AnimatePresence>
                </motion.button>
              );
            })}
          </div>
        </nav>

        {/* Footer */}
        <div className="p-3 border-t border-casino-border shrink-0">
          <AnimatePresence mode="wait">
            {sidebarOpen && (
              <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="text-center text-xs text-gray-500">
                <p>Provably Fair Gaming</p>
                <p className="text-gray-600 mt-1">v2.0.0</p>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </motion.aside>
    </>
  );
};

export default Sidebar;
