import { motion } from 'framer-motion';
import {
    AlertCircle,
    Check,
    Copy,
    Hash, Key,
    RefreshCw,
    Shield,
    X
} from 'lucide-react';
import { useState } from 'react';
import { useCasino } from '../../context/CasinoContext';

const ProvablyFairModal = ({ onClose }) => {
  const { state, setClientSeed, rotateServerSeed } = useCasino();
  const [newClientSeed, setNewClientSeed] = useState(state.clientSeed);
  const [copied, setCopied] = useState(null);
  const [showPreviousSeeds, setShowPreviousSeeds] = useState(false);

  const handleCopy = (text, field) => {
    navigator.clipboard.writeText(text);
    setCopied(field);
    setTimeout(() => setCopied(null), 2000);
  };

  const handleClientSeedChange = () => {
    setClientSeed(newClientSeed);
  };

  const handleRotateServerSeed = () => {
    if (confirm('Rotating the server seed will reveal the current server seed and reset the nonce. Continue?')) {
      rotateServerSeed();
    }
  };

  const generateRandomSeed = () => {
    const chars = '0123456789abcdef';
    let result = '';
    const array = new Uint8Array(16);
    crypto.getRandomValues(array);
    for (let i = 0; i < 16; i++) {
      result += chars[array[i] % 16];
    }
    setNewClientSeed(result);
  };

  return (
    <div className="bg-casino-card border border-casino-border rounded-2xl overflow-hidden max-h-[80vh] overflow-y-auto">
      {/* Header */}
      <div className="flex items-center justify-between p-6 border-b border-casino-border sticky top-0 bg-casino-card z-10">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-lg bg-casino-green/20 border border-casino-green flex items-center justify-center">
            <Shield className="w-5 h-5 text-casino-green" />
          </div>
          <div>
            <h2 className="font-display font-bold text-xl">Provably Fair</h2>
            <p className="text-xs text-gray-500">Verify every bet outcome</p>
          </div>
        </div>
        <button
          onClick={onClose}
          className="p-2 rounded-lg hover:bg-white/10 transition-colors"
        >
          <X className="w-5 h-5" />
        </button>
      </div>

      {/* Content */}
      <div className="p-6 space-y-6">
        {/* Info box */}
        <div className="bg-casino-green/10 border border-casino-green/30 rounded-lg p-4">
          <div className="flex gap-3">
            <AlertCircle className="w-5 h-5 text-casino-green shrink-0 mt-0.5" />
            <div className="text-sm text-gray-300">
              <p className="mb-2">
                Every game outcome is determined by combining three values:
              </p>
              <ul className="list-disc list-inside space-y-1 text-gray-400">
                <li><strong className="text-white">Server Seed</strong> - Hidden until revealed</li>
                <li><strong className="text-white">Client Seed</strong> - Set by you</li>
                <li><strong className="text-white">Nonce</strong> - Increments with each bet</li>
              </ul>
            </div>
          </div>
        </div>

        {/* Server Seed Hash */}
        <section>
          <label className="flex items-center gap-2 text-sm font-bold uppercase tracking-wider text-casino-cyan mb-3">
            <Key className="w-4 h-4" />
            Server Seed (Hashed)
          </label>
          <div className="flex gap-2">
            <div className="flex-1 bg-casino-bg border border-casino-border rounded-lg px-4 py-3 font-mono text-sm text-gray-400 truncate">
              {state.serverSeedHash || 'Generating...'}
            </div>
            <button
              onClick={() => handleCopy(state.serverSeedHash, 'serverHash')}
              className="px-4 py-3 rounded-lg border border-casino-border hover:bg-white/5 transition-colors"
              title="Copy"
            >
              {copied === 'serverHash' ? (
                <Check className="w-4 h-4 text-casino-green" />
              ) : (
                <Copy className="w-4 h-4" />
              )}
            </button>
          </div>
          <p className="text-xs text-gray-600 mt-2">
            This is the SHA-256 hash of the server seed. The actual seed will be revealed when you rotate seeds.
          </p>
        </section>

        {/* Client Seed */}
        <section>
          <label className="flex items-center gap-2 text-sm font-bold uppercase tracking-wider text-casino-purple mb-3">
            <Key className="w-4 h-4" />
            Client Seed
          </label>
          <div className="flex gap-2">
            <input
              type="text"
              value={newClientSeed}
              onChange={(e) => setNewClientSeed(e.target.value)}
              className="flex-1 bg-casino-bg border border-casino-border rounded-lg px-4 py-3 font-mono text-sm focus:border-casino-purple focus:outline-none transition-colors"
              placeholder="Enter your client seed"
            />
            <button
              onClick={generateRandomSeed}
              className="px-4 py-3 rounded-lg border border-casino-border hover:bg-white/5 transition-colors"
              title="Generate Random"
            >
              <RefreshCw className="w-4 h-4" />
            </button>
            <button
              onClick={() => handleCopy(newClientSeed, 'client')}
              className="px-4 py-3 rounded-lg border border-casino-border hover:bg-white/5 transition-colors"
              title="Copy"
            >
              {copied === 'client' ? (
                <Check className="w-4 h-4 text-casino-green" />
              ) : (
                <Copy className="w-4 h-4" />
              )}
            </button>
          </div>

          {newClientSeed !== state.clientSeed && (
            <motion.button
              initial={{ opacity: 0, y: -10 }}
              animate={{ opacity: 1, y: 0 }}
              onClick={handleClientSeedChange}
              className="mt-3 w-full py-2 rounded-lg bg-casino-purple text-white font-medium hover:bg-casino-purple/80 transition-colors"
            >
              Update Client Seed
            </motion.button>
          )}
        </section>

        {/* Nonce */}
        <section>
          <label className="flex items-center gap-2 text-sm font-bold uppercase tracking-wider text-casino-gold mb-3">
            <Hash className="w-4 h-4" />
            Nonce
          </label>
          <div className="bg-casino-bg border border-casino-border rounded-lg px-4 py-3">
            <span className="font-display font-bold text-2xl text-casino-gold">
              {state.nonce}
            </span>
            <span className="text-gray-500 ml-2">bets made with current seeds</span>
          </div>
          <p className="text-xs text-gray-600 mt-2">
            The nonce is incremented after each bet and resets when you rotate seeds.
          </p>
        </section>

        {/* Rotate Server Seed */}
        <section className="pt-4 border-t border-casino-border">
          <button
            onClick={handleRotateServerSeed}
            className="w-full flex items-center justify-center gap-2 py-3 rounded-lg border border-casino-cyan text-casino-cyan hover:bg-casino-cyan hover:text-casino-bg transition-all font-medium"
          >
            <RefreshCw className="w-4 h-4" />
            Rotate Server Seed
          </button>
          <p className="text-xs text-gray-600 mt-2 text-center">
            Reveals the current server seed and generates a new one. This resets the nonce.
          </p>
        </section>

        {/* Verification formula */}
        <section className="pt-4 border-t border-casino-border">
          <h3 className="text-sm font-bold uppercase tracking-wider text-white mb-3">
            Verification Formula
          </h3>
          <div className="bg-casino-bg border border-casino-border rounded-lg p-4 font-mono text-sm">
            <p className="text-gray-400 mb-2">// Combined seed</p>
            <p className="text-casino-cyan">
              combinedSeed = serverSeed + "-" + clientSeed + "-" + nonce
            </p>
            <p className="text-gray-400 mt-4 mb-2">// Generate outcome hash</p>
            <p className="text-casino-purple">
              hash = SHA256(combinedSeed)
            </p>
            <p className="text-gray-400 mt-4 mb-2">// Convert to game result</p>
            <p className="text-casino-gold">
              result = gameFunction(hash)
            </p>
          </div>
        </section>
      </div>
    </div>
  );
};

export default ProvablyFairModal;
