import { motion } from 'framer-motion';
import { useCallback, useRef, useState } from 'react';
import BetControls from '../components/BetControls';
import { useCasino } from '../context/CasinoContext';
import { playSound } from '../utils/audioEngine';

const getRandomFloat = () => {
  const array = new Uint32Array(1);
  crypto.getRandomValues(array);
  return array[0] / (0xFFFFFFFF + 1);
};

const DiceGame = () => {
  const { state, addBalance, subtractBalance } = useCasino();
  const balance = state.balance;
  const soundEnabled = state.settings?.soundEnabled;

  const [betAmount, setBetAmount] = useState(10);
  const [targetValue, setTargetValue] = useState(50);
  const [isRollOver, setIsRollOver] = useState(true);
  const [rolling, setRolling] = useState(false);
  const [result, setResult] = useState(null);
  const [displayValue, setDisplayValue] = useState(50);
  const [history, setHistory] = useState([]);

  // Auto-bet state
  const [autoActive, setAutoActive] = useState(false);
  const [autoBetsRemaining, setAutoBetsRemaining] = useState(0);
  const autoTimeoutRef = useRef(null);
  const autoSettingsRef = useRef({});

  const winChance = isRollOver ? (100 - targetValue) : targetValue;
  const multiplier = Math.max(0.01, (100 / winChance) * 0.99).toFixed(4);
  const potentialWin = (betAmount * parseFloat(multiplier)).toFixed(2);

  const roll = useCallback((bet = betAmount) => {
    if (bet > balance || rolling) return;

    subtractBalance(bet);
    setRolling(true);
    setResult(null);
    if (soundEnabled) playSound('diceRoll');

    // Animate rolling
    let animationFrame;
    const startTime = Date.now();
    const duration = 1000;

    const animate = () => {
      const elapsed = Date.now() - startTime;
      if (elapsed < duration) {
        setDisplayValue((getRandomFloat() * 100).toFixed(2));
        animationFrame = requestAnimationFrame(animate);
      } else {
        // Final result
        const finalValue = (getRandomFloat() * 100).toFixed(2);
        setDisplayValue(finalValue);

        const won = isRollOver
          ? parseFloat(finalValue) > targetValue
          : parseFloat(finalValue) < targetValue;

        if (won) {
          const winAmount = bet * parseFloat(multiplier);
          addBalance(winAmount);
          setResult({ won: true, value: finalValue, amount: winAmount });
          if (soundEnabled) playSound('betWin');
        } else {
          setResult({ won: false, value: finalValue, amount: 0 });
          if (soundEnabled) playSound('betLose');
        }

        setHistory(prev => [{
          value: finalValue,
          target: targetValue,
          isRollOver,
          won
        }, ...prev.slice(0, 19)]);

        setRolling(false);
        return { won };
      }
    };

    animate();
    return new Promise(resolve => {
      setTimeout(() => {
        const finalValue = (getRandomFloat() * 100).toFixed(2);
        const won = isRollOver
          ? parseFloat(finalValue) > targetValue
          : parseFloat(finalValue) < targetValue;
        resolve({ won });
      }, duration);
    });
  }, [betAmount, balance, rolling, subtractBalance, isRollOver, targetValue, multiplier, addBalance, soundEnabled]);

  const handleAutoStart = useCallback((settings) => {
    autoSettingsRef.current = settings;
    setAutoActive(true);
    setAutoBetsRemaining(settings.numberOfBets === Infinity ? -1 : settings.numberOfBets);

    const runAutoBet = async () => {
      const settings = autoSettingsRef.current;

      if (betAmount > balance) {
        setAutoActive(false);
        setAutoBetsRemaining(0);
        return;
      }

      const res = await roll(betAmount);

      setAutoBetsRemaining(prev => {
        if (prev === -1) return -1;
        return prev - 1;
      });

      // Check stop conditions
      if (settings.stopOnWin && res?.won) {
        setAutoActive(false);
        setAutoBetsRemaining(0);
        return;
      }
      if (settings.stopOnLoss && !res?.won) {
        setAutoActive(false);
        setAutoBetsRemaining(0);
        return;
      }

      // Continue auto betting
      autoTimeoutRef.current = setTimeout(() => {
        setAutoBetsRemaining(prev => {
          if (prev === 0) {
            setAutoActive(false);
            return 0;
          }
          runAutoBet();
          return prev;
        });
      }, 1500);
    };

    runAutoBet();
  }, [betAmount, balance, roll]);

  const handleAutoStop = useCallback(() => {
    setAutoActive(false);
    setAutoBetsRemaining(0);
    if (autoTimeoutRef.current) {
      clearTimeout(autoTimeoutRef.current);
    }
  }, []);

  const toggleMode = () => {
    setIsRollOver(!isRollOver);
  };

  return (
    <div className="h-full flex flex-col lg:flex-row gap-4">
      <div className="flex-1 flex flex-col">
        {/* Main display */}
        <div className="flex-1 bg-casino-card border border-casino-border rounded-xl p-6 flex flex-col items-center justify-center">

          {/* Result display */}
          <motion.div
            key={displayValue}
            animate={rolling ? { scale: [1, 1.05, 1] } : {}}
            transition={{ duration: 0.1 }}
            className={`text-8xl md:text-9xl font-black mb-8 ${
              result ? (result.won ? 'text-casino-green' : 'text-casino-red') : 'text-white'
            }`}
          >
            {displayValue}
          </motion.div>

          {/* Result message */}
          {result && (
            <motion.div
              initial={{ scale: 0 }}
              animate={{ scale: 1 }}
              className={`px-6 py-3 rounded-xl text-xl font-bold ${
                result.won ? 'bg-casino-green/20 text-casino-green' : 'bg-casino-red/20 text-casino-red'
              }`}
            >
              {result.won ? `WIN! +$${result.amount.toFixed(2)}` : 'LOSS'}
            </motion.div>
          )}

          {/* Slider */}
          <div className="w-full max-w-md mt-8">
            <div className="relative h-4 bg-gray-700 rounded-full overflow-hidden">
              <div
                className={`absolute h-full transition-all ${
                  isRollOver ? 'bg-casino-green right-0' : 'bg-casino-green left-0'
                }`}
                style={{
                  width: `${isRollOver ? 100 - targetValue : targetValue}%`
                }}
              />
              <div
                className="absolute w-1 h-full bg-white"
                style={{ left: `${targetValue}%`, transform: 'translateX(-50%)' }}
              />
            </div>
            <input
              type="range"
              min={2}
              max={98}
              value={targetValue}
              onChange={(e) => setTargetValue(parseInt(e.target.value))}
              disabled={rolling || autoActive}
              className="w-full mt-2 slider-thumb"
            />
            <div className="flex justify-between text-sm text-gray-500 mt-1">
              <span>0</span>
              <span>{targetValue}</span>
              <span>100</span>
            </div>
          </div>

          {/* Stats grid */}
          <div className="grid grid-cols-3 gap-4 w-full max-w-md mt-6">
            <div className="bg-casino-bg rounded-lg p-3 text-center">
              <div className="text-xs text-gray-500 uppercase">Multiplier</div>
              <div className="text-lg font-bold text-casino-gold">{multiplier}x</div>
            </div>
            <div className="bg-casino-bg rounded-lg p-3 text-center">
              <button
                onClick={toggleMode}
                disabled={rolling || autoActive}
                className="w-full"
              >
                <div className="text-xs text-gray-500 uppercase">Roll</div>
                <div className="text-lg font-bold text-white">
                  {isRollOver ? `Over ${targetValue}` : `Under ${targetValue}`}
                </div>
              </button>
            </div>
            <div className="bg-casino-bg rounded-lg p-3 text-center">
              <div className="text-xs text-gray-500 uppercase">Win Chance</div>
              <div className="text-lg font-bold text-casino-cyan">{winChance.toFixed(2)}%</div>
            </div>
          </div>
        </div>

        {/* History */}
        <div className="flex gap-2 mt-4 overflow-x-auto pb-2">
          {history.map((h, i) => (
            <motion.div
              key={i}
              initial={{ scale: 0 }}
              animate={{ scale: 1 }}
              className={`shrink-0 px-3 py-1.5 rounded text-xs font-bold ${
                h.won ? 'bg-casino-green/20 text-casino-green' : 'bg-casino-red/20 text-casino-red'
              }`}
            >
              {h.value}
            </motion.div>
          ))}
        </div>
      </div>

      <div className="w-full lg:w-80 space-y-4">
        <BetControls
          betAmount={betAmount}
          onBetChange={setBetAmount}
          onBet={() => roll()}
          balance={balance}
          disabled={rolling || autoActive}
          buttonText={rolling ? "ROLLING..." : "ROLL"}
          showAutoBet={true}
          autoActive={autoActive}
          autoBetsRemaining={autoBetsRemaining}
          onAutoStart={handleAutoStart}
          onAutoStop={handleAutoStop}
        />

        <div className="bg-casino-card border border-casino-border rounded-xl p-4">
          <div className="flex justify-between items-center mb-2">
            <span className="text-xs text-gray-500 uppercase">Potential Win</span>
            <span className="text-lg font-bold text-casino-green">${potentialWin}</span>
          </div>
        </div>

        <div className="bg-casino-card border border-casino-border rounded-xl p-4">
          <p className="text-xs text-gray-500 leading-relaxed">
            Roll a number between 0 and 100. Win if your roll is {isRollOver ? 'over' : 'under'} the target.
            Higher risk = higher reward. Click the Roll text to toggle over/under.
          </p>
        </div>
      </div>
    </div>
  );
};

export default DiceGame;
