import { AnimatePresence, motion } from 'framer-motion';
import { Cherry, Coins, Crown, Diamond, Gem, Star, Zap } from 'lucide-react';
import { useCallback, useEffect, useRef, useState } from 'react';
import BetControls from '../components/BetControls';
import { useCasino } from '../context/CasinoContext';
import { playSound } from '../utils/audioEngine';

const getRandomFloat = () => {
  const array = new Uint32Array(1);
  crypto.getRandomValues(array);
  return array[0] / (0xffffffff + 1);
};

const SYMBOLS = [
  { id: 'cherry', icon: Cherry, color: 'text-red-500', weight: 30 },
  { id: 'coin', icon: Coins, color: 'text-yellow-500', weight: 25 },
  { id: 'gem', icon: Gem, color: 'text-purple-500', weight: 20 },
  { id: 'star', icon: Star, color: 'text-casino-gold', weight: 12 },
  { id: 'diamond', icon: Diamond, color: 'text-cyan-400', weight: 8 },
  { id: 'crown', icon: Crown, color: 'text-casino-cyan', weight: 4 },
  { id: 'seven', icon: Zap, color: 'text-casino-green', weight: 1 }
];

const PAYOUTS = {
  cherry: { 3: 2, 4: 5, 5: 10 },
  coin: { 3: 3, 4: 8, 5: 15 },
  gem: { 3: 5, 4: 12, 5: 25 },
  star: { 3: 10, 4: 25, 5: 50 },
  diamond: { 3: 20, 4: 50, 5: 100 },
  crown: { 3: 50, 4: 125, 5: 250 },
  seven: { 3: 100, 4: 500, 5: 1000 }
};

// Create weighted array for random selection
const createWeightedArray = () => {
  const weighted = [];
  SYMBOLS.forEach((s) => {
    for (let i = 0; i < s.weight; i++) {
      weighted.push(s.id);
    }
  });
  return weighted;
};

const WEIGHTED_SYMBOLS = createWeightedArray();

const getRandomSymbol = () => {
  const index = Math.floor(getRandomFloat() * WEIGHTED_SYMBOLS.length);
  return WEIGHTED_SYMBOLS[index];
};

// Single Reel component with CSS animation
const Reel = ({ finalSymbols, spinning, reelIndex, onComplete }) => {
  const [displaySymbols, setDisplaySymbols] = useState(finalSymbols);
  const [animating, setAnimating] = useState(false);
  const spinSoundPlayed = useRef(false);

  useEffect(() => {
    if (spinning) {
      setAnimating(true);
      spinSoundPlayed.current = false;

      // Spin duration increases per reel
      const spinDuration = 1000 + reelIndex * 400;

      // Rapid symbol changes during spin
      const interval = setInterval(() => {
        setDisplaySymbols([
          getRandomSymbol(),
          getRandomSymbol(),
          getRandomSymbol()
        ]);
      }, 80);

      // Stop and show final
      setTimeout(() => {
        clearInterval(interval);
        setDisplaySymbols(finalSymbols);
        setAnimating(false);
        if (onComplete) onComplete(reelIndex);
      }, spinDuration);

      return () => clearInterval(interval);
    }
  }, [spinning, finalSymbols, reelIndex, onComplete]);

  return (
    <div className={`relative h-[160px] w-14 sm:w-16 overflow-hidden bg-casino-bg/80 rounded-lg border-2 ${animating ? 'border-casino-cyan' : 'border-casino-border'}`}>
      {/* Blur effect during spin */}
      <div className={`absolute inset-0 flex flex-col items-center justify-around py-2 transition-all ${animating ? 'blur-sm' : ''}`}>
        {displaySymbols.map((symbolId, i) => {
          const symbol = SYMBOLS.find((s) => s.id === symbolId);
          if (!symbol) return null;
          const Icon = symbol.icon;
          return (
            <motion.div
              key={i}
              className={`flex items-center justify-center ${symbol.color}`}
              animate={animating ? { y: [0, 10, 0], scale: [1, 0.9, 1] } : {}}
              transition={{ duration: 0.15, repeat: animating ? Infinity : 0 }}
            >
              <Icon className="w-10 h-10 sm:w-12 sm:h-12" />
            </motion.div>
          );
        })}
      </div>
    </div>
  );
};

const SlotsGame = () => {
  const { state, addBalance, subtractBalance } = useCasino();
  const balance = state.balance;
  const soundEnabled = state.settings?.soundEnabled;

  const [betAmount, setBetAmount] = useState(10);
  const [spinning, setSpinning] = useState(false);
  const [reels, setReels] = useState([
    ['cherry', 'coin', 'gem'],
    ['cherry', 'coin', 'gem'],
    ['cherry', 'coin', 'gem'],
    ['cherry', 'coin', 'gem'],
    ['cherry', 'coin', 'gem']
  ]);
  const [lastWin, setLastWin] = useState(null);
  const [winningLines, setWinningLines] = useState([]);
  const [history, setHistory] = useState([]);

  // Auto-bet state
  const [autoBetActive, setAutoBetActive] = useState(false);
  const [autoBetsRemaining, setAutoBetsRemaining] = useState(0);
  const autoTimeoutRef = useRef(null);
  const completedReelsRef = useRef(0);

  const checkWins = useCallback((reelResults) => {
    const wins = { totalWin: 0, lines: [] };

    // Check each row (3 rows)
    for (let row = 0; row < 3; row++) {
      const lineSymbols = reelResults.map((reel) => reel[row]);

      // Count consecutive matches from left
      let matchCount = 1;
      const firstSymbol = lineSymbols[0];

      for (let i = 1; i < 5; i++) {
        if (lineSymbols[i] === firstSymbol) {
          matchCount++;
        } else {
          break;
        }
      }

      if (matchCount >= 3 && PAYOUTS[firstSymbol]) {
        const payout = PAYOUTS[firstSymbol][matchCount] || 0;
        if (payout > 0) {
          wins.totalWin += payout;
          wins.lines.push({ row, symbol: firstSymbol, count: matchCount, payout });
        }
      }
    }

    return wins;
  }, []);

  const handleSpinComplete = useCallback((reelIndex) => {
    completedReelsRef.current++;

    if (soundEnabled) playSound('slotStop');

    // When all reels complete
    if (completedReelsRef.current >= 5) {
      completedReelsRef.current = 0;

      // Slight delay then check wins
      setTimeout(() => {
        const wins = checkWins(reels);
        if (wins.totalWin > 0) {
          const winAmount = wins.totalWin * betAmount;
          addBalance(winAmount);
          setLastWin({ amount: winAmount, multiplier: wins.totalWin, lines: wins.lines });
          setWinningLines(wins.lines);
          setHistory((prev) => [{ won: true, multiplier: wins.totalWin }, ...prev.slice(0, 14)]);
          if (soundEnabled) {
            if (wins.totalWin >= 50) playSound('jackpot');
            else if (wins.totalWin >= 10) playSound('bigWin');
            else playSound('betWin');
          }
        } else {
          setHistory((prev) => [{ won: false, multiplier: 0 }, ...prev.slice(0, 14)]);
          if (soundEnabled) playSound('betLose');
        }
        setSpinning(false);
      }, 200);
    }
  }, [reels, betAmount, addBalance, checkWins, soundEnabled]);

  const spin = useCallback(() => {
    if (spinning || betAmount > balance) return;

    subtractBalance(betAmount);
    setSpinning(true);
    setLastWin(null);
    setWinningLines([]);
    completedReelsRef.current = 0;

    if (soundEnabled) playSound('slotSpin');

    // Generate final results for all reels
    const newReels = Array.from({ length: 5 }, () =>
      Array.from({ length: 3 }, () => getRandomSymbol())
    );
    setReels(newReels);
  }, [spinning, betAmount, balance, subtractBalance, soundEnabled]);

  // Auto-bet handlers
  const startAutoBet = useCallback((numBets) => {
    if (spinning || betAmount > balance) return;

    setAutoBetActive(true);
    setAutoBetsRemaining(numBets);
  }, [spinning, betAmount, balance]);

  const stopAutoBet = useCallback(() => {
    setAutoBetActive(false);
    setAutoBetsRemaining(0);
    if (autoTimeoutRef.current) {
      clearTimeout(autoTimeoutRef.current);
      autoTimeoutRef.current = null;
    }
  }, []);

  // Handle auto-spin continuation after spin is fully complete
  useEffect(() => {
    if (!spinning && autoBetActive && autoBetsRemaining > 0 && betAmount <= balance) {
      // Delay before next spin
      autoTimeoutRef.current = setTimeout(() => {
        setAutoBetsRemaining(prev => prev - 1);
        spin();
      }, 1500);
      
      return () => {
        if (autoTimeoutRef.current) {
          clearTimeout(autoTimeoutRef.current);
        }
      };
    }
  }, [spinning, autoBetActive, autoBetsRemaining, betAmount, balance, spin]);

  // Cleanup
  useEffect(() => {
    return () => {
      if (autoTimeoutRef.current) {
        clearTimeout(autoTimeoutRef.current);
      }
    };
  }, []);

  return (
    <div className="h-full flex flex-col lg:flex-row gap-4">
      <div className="flex-1 flex flex-col">
        {/* Slot Machine */}
        <div className="flex-1 bg-casino-card border border-casino-border rounded-xl p-4 flex flex-col items-center justify-center">
          {/* Machine Frame */}
          <div className="bg-gradient-to-b from-casino-gold/20 to-casino-gold/5 border-4 border-casino-gold/50 rounded-2xl p-4 sm:p-6 shadow-2xl">
            {/* Header */}
            <div className="text-center mb-4">
              <h2 className="text-xl sm:text-2xl font-black text-casino-gold tracking-wider">LUCKY SLOTS</h2>
              <div className="flex justify-center gap-1 mt-2">
                {[...Array(5)].map((_, i) => (
                  <Star key={i} className="w-3 h-3 sm:w-4 sm:h-4 text-casino-gold fill-casino-gold" />
                ))}
              </div>
            </div>

            {/* Reels Container */}
            <div className="bg-casino-bg/80 rounded-xl p-3 sm:p-4 border-2 border-casino-border">
              <div className="flex gap-1 sm:gap-2 justify-center">
                {reels.map((reelSymbols, i) => (
                  <Reel
                    key={i}
                    finalSymbols={reelSymbols}
                    spinning={spinning}
                    reelIndex={i}
                    onComplete={handleSpinComplete}
                  />
                ))}
              </div>

              {/* Payline indicators */}
              <div className="flex justify-center gap-2 mt-3">
                {[1, 2, 3].map((line) => (
                  <div
                    key={line}
                    className={`text-xs font-bold px-2 py-1 rounded transition-colors ${
                      winningLines.some((w) => w.row === line - 1)
                        ? 'bg-casino-green text-casino-bg animate-pulse'
                        : 'bg-casino-border text-gray-500'
                    }`}
                  >
                    LINE {line}
                  </div>
                ))}
              </div>
            </div>

            {/* Spin indicator */}
            {spinning && (
              <motion.div
                className="text-center mt-4"
                animate={{ opacity: [0.5, 1, 0.5] }}
                transition={{ duration: 0.5, repeat: Infinity }}
              >
                <span className="text-casino-cyan font-bold">SPINNING...</span>
              </motion.div>
            )}
          </div>
        </div>

        {/* Win Display */}
        <AnimatePresence>
          {lastWin && (
            <motion.div
              initial={{ opacity: 0, scale: 0.5 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0 }}
              className="mt-4 text-center"
            >
              <motion.div
                className="text-3xl font-black text-casino-green"
                animate={{ scale: [1, 1.1, 1] }}
                transition={{ duration: 0.3, repeat: 3 }}
              >
                WIN! +${lastWin.amount.toFixed(2)}
              </motion.div>
              <div className="text-sm text-gray-400 mt-1 flex flex-wrap justify-center gap-2">
                {lastWin.lines.map((l, i) => (
                  <span key={i} className="bg-casino-green/20 px-2 py-0.5 rounded">
                    Line {l.row + 1}: {l.count}x {l.symbol} ({l.payout}x)
                  </span>
                ))}
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        {/* History - Limited */}
        <div className="flex gap-2 mt-4 overflow-x-auto pb-2 max-h-12">
          {history.slice(0, 15).map((h, i) => (
            <motion.div
              key={i}
              initial={{ scale: 0 }}
              animate={{ scale: 1 }}
              className={`shrink-0 px-3 py-1.5 rounded text-xs font-bold ${
                h.won ? 'bg-casino-green/20 text-casino-green' : 'bg-casino-red/20 text-casino-red'
              }`}
            >
              {h.won ? `${h.multiplier}x` : 'MISS'}
            </motion.div>
          ))}
        </div>
      </div>

      <div className="w-full lg:w-80 space-y-4">
        <BetControls
          betAmount={betAmount}
          onBetChange={setBetAmount}
          onBet={spin}
          balance={balance}
          disabled={spinning || autoBetActive}
          buttonText={spinning ? 'SPINNING...' : 'SPIN'}
          showAutoBet={false}
        />

        {/* Auto Bet Controls */}
        <div className="bg-casino-card border border-casino-border rounded-xl p-4">
          <div className="flex items-center justify-between mb-3">
            <span className="text-xs font-bold uppercase text-gray-400">Auto Spin</span>
            {autoBetActive && (
              <span className="text-xs text-casino-cyan">{autoBetsRemaining} remaining</span>
            )}
          </div>

          {autoBetActive ? (
            <button
              onClick={stopAutoBet}
              className="w-full py-3 bg-casino-red text-white rounded-xl font-bold hover:brightness-110 transition"
            >
              STOP AUTO
            </button>
          ) : (
            <div className="grid grid-cols-4 gap-2">
              {[10, 25, 50, 100].map((count) => (
                <button
                  key={count}
                  onClick={() => startAutoBet(count)}
                  disabled={spinning || betAmount > balance}
                  className="py-2 bg-casino-border hover:bg-casino-cyan/30 rounded-lg text-sm font-bold transition disabled:opacity-50"
                >
                  {count}
                </button>
              ))}
            </div>
          )}
        </div>

        {/* Paytable */}
        <div className="bg-casino-card border border-casino-border rounded-xl p-4">
          <h3 className="text-xs text-gray-500 uppercase mb-3">Paytable</h3>
          <div className="space-y-2 text-xs max-h-40 overflow-y-auto">
            {SYMBOLS.map((symbol) => {
              const Icon = symbol.icon;
              return (
                <div key={symbol.id} className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <Icon className={`w-4 h-4 ${symbol.color}`} />
                    <span className="text-gray-400 capitalize">{symbol.id}</span>
                  </div>
                  <div className="flex gap-2 text-gray-500 text-[10px]">
                    <span>3x:{PAYOUTS[symbol.id][3]}</span>
                    <span>4x:{PAYOUTS[symbol.id][4]}</span>
                    <span>5x:{PAYOUTS[symbol.id][5]}</span>
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        <div className="bg-casino-card border border-casino-border rounded-xl p-4">
          <div className="flex items-center gap-2 mb-2">
            <Star className="w-4 h-4 text-casino-gold" />
            <span className="text-xs font-bold uppercase tracking-wider text-gray-400">How to Play</span>
          </div>
          <p className="text-xs text-gray-500 leading-relaxed">
            Match 3+ symbols on any of the 3 horizontal paylines to win! Payouts multiply your bet.
          </p>
        </div>
      </div>
    </div>
  );
};

export default SlotsGame;
