import { motion } from 'framer-motion';
import { DollarSign, Play, RefreshCw, Square } from 'lucide-react';
import { useEffect, useState } from 'react';

const BetControls = ({
  betAmount,
  onBetChange,
  onBet,
  onCashout,
  balance,
  disabled = false,
  isPlaying = false,
  showCashout = false,
  cashoutAmount = 0,
  multiplier = 1,
  minBet = 0.01,
  maxBet = 10000,
  showMultiplier = false,
  buttonText = null,
  buttonClassName = '',
  // Auto bet props
  showAutoBet = true,
  autoActive = false,
  onAutoStart = null,
  onAutoStop = null,
  autoBetsRemaining = 0,
  children
}) => {
  const [inputValue, setInputValue] = useState(betAmount.toString());
  const [showAutoPanel, setShowAutoPanel] = useState(false);
  const [autoConfig, setAutoConfig] = useState({
    numberOfBets: 10,
    stopOnWin: false,
    stopOnLoss: false,
    stopOnProfit: '',
    stopOnLossAmount: '',
    onWinAction: 'reset',
    onLossAction: 'reset'
  });

  useEffect(() => {
    if (!isPlaying) {
      setInputValue(betAmount.toFixed(2));
    }
  }, [betAmount, isPlaying]);

  const handleInputChange = (e) => {
    const value = e.target.value;
    setInputValue(value);
    const num = parseFloat(value);
    if (!isNaN(num) && num >= 0) {
      onBetChange(Math.min(num, maxBet));
    }
  };

  const handleBlur = () => {
    const num = parseFloat(inputValue);
    if (isNaN(num) || num < minBet) {
      setInputValue(minBet.toString());
      onBetChange(minBet);
    } else {
      setInputValue(betAmount.toFixed(2));
    }
  };

  const adjustBet = (action) => {
    let newBet = betAmount;
    switch (action) {
      case 'half':
        newBet = Math.max(minBet, betAmount / 2);
        break;
      case 'double':
        newBet = Math.min(maxBet, Math.min(balance, betAmount * 2));
        break;
      case 'min':
        newBet = minBet;
        break;
      case 'max':
        newBet = Math.min(maxBet, balance);
        break;
      default:
        break;
    }
    onBetChange(newBet);
    setInputValue(newBet.toFixed(2));
  };

  const canBet = balance >= betAmount && betAmount >= minBet && !disabled && !isPlaying;

  const handleAutoStart = () => {
    if (onAutoStart) {
      onAutoStart(betAmount, {
        ...autoConfig,
        stopOnProfit: autoConfig.stopOnProfit ? parseFloat(autoConfig.stopOnProfit) : null,
        stopOnLossAmount: autoConfig.stopOnLossAmount ? parseFloat(autoConfig.stopOnLossAmount) : null
      });
    }
  };

  return (
    <div className="bg-casino-card border border-casino-border rounded-xl p-4 space-y-4">
      {/* Bet amount input */}
      <div>
        <label className="flex items-center justify-between text-xs text-gray-500 uppercase tracking-wider mb-2">
          <span>Bet Amount</span>
          <span className="text-casino-cyan">${balance.toFixed(2)}</span>
        </label>

        <div className="flex gap-2">
          <div className="flex-1 relative">
            <DollarSign className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-500" />
            <input
              type="number"
              value={inputValue}
              onChange={handleInputChange}
              onBlur={handleBlur}
              disabled={disabled || isPlaying || autoActive}
              className="w-full bg-casino-bg border border-casino-border rounded-lg pl-9 pr-4 py-3 font-mono text-lg focus:border-casino-cyan focus:outline-none transition-colors disabled:opacity-50"
              min={minBet}
              max={maxBet}
              step="0.01"
            />
          </div>

          <div className="flex gap-1">
            <QuickButton onClick={() => adjustBet('half')} disabled={disabled || isPlaying || autoActive}>
              ½
            </QuickButton>
            <QuickButton onClick={() => adjustBet('double')} disabled={disabled || isPlaying || autoActive}>
              2×
            </QuickButton>
          </div>
        </div>

        <div className="flex gap-2 mt-2">
          <button
            onClick={() => adjustBet('min')}
            disabled={disabled || isPlaying || autoActive}
            className="flex-1 py-1.5 text-xs text-gray-500 hover:text-white border border-casino-border rounded-lg hover:bg-white/5 transition-colors disabled:opacity-50"
          >
            Min
          </button>
          <button
            onClick={() => adjustBet('max')}
            disabled={disabled || isPlaying || autoActive}
            className="flex-1 py-1.5 text-xs text-gray-500 hover:text-white border border-casino-border rounded-lg hover:bg-white/5 transition-colors disabled:opacity-50"
          >
            Max
          </button>
        </div>
      </div>

      {children}

      {showMultiplier && multiplier > 1 && (
        <div className="bg-casino-bg border border-casino-border rounded-lg p-3">
          <div className="flex items-center justify-between">
            <span className="text-xs text-gray-500 uppercase tracking-wider">Multiplier</span>
            <span className="font-display font-bold text-xl text-casino-cyan">
              {multiplier.toFixed(2)}x
            </span>
          </div>
          <div className="flex items-center justify-between mt-1">
            <span className="text-xs text-gray-500">Potential Win</span>
            <span className="font-mono text-casino-green">
              ${(betAmount * multiplier).toFixed(2)}
            </span>
          </div>
        </div>
      )}

      {/* Main action button */}
      {showCashout && isPlaying ? (
        <motion.button
          onClick={onCashout}
          className="w-full py-4 rounded-xl bg-casino-green text-casino-bg font-display font-bold text-lg uppercase tracking-wider shadow-neon-green hover:scale-[1.02] active:scale-[0.98] transition-transform"
          whileHover={{ scale: 1.02 }}
          whileTap={{ scale: 0.98 }}
        >
          <div className="flex items-center justify-center gap-2">
            <span>Cash Out</span>
            <span className="text-2xl">${cashoutAmount.toFixed(2)}</span>
          </div>
        </motion.button>
      ) : autoActive ? (
        <motion.button
          onClick={onAutoStop}
          className="w-full py-4 rounded-xl bg-casino-red text-white font-display font-bold text-lg uppercase tracking-wider"
          whileHover={{ scale: 1.02 }}
          whileTap={{ scale: 0.98 }}
        >
          <div className="flex items-center justify-center gap-2">
            <Square className="w-5 h-5" />
            <span>Stop Auto ({autoBetsRemaining})</span>
          </div>
        </motion.button>
      ) : (
        <motion.button
          onClick={onBet}
          disabled={!canBet}
          className={`w-full py-4 rounded-xl font-display font-bold text-lg uppercase tracking-wider transition-all ${
            buttonClassName ? buttonClassName : (canBet
              ? 'bg-casino-cyan text-casino-bg shadow-neon-cyan hover:scale-[1.02] active:scale-[0.98]'
              : 'bg-casino-border text-gray-600 cursor-not-allowed')
          }`}
          whileHover={canBet ? { scale: 1.02 } : {}}
          whileTap={canBet ? { scale: 0.98 } : {}}
        >
          <div className="flex items-center justify-center gap-2">
            {buttonText ? (
              <span>{buttonText}</span>
            ) : isPlaying ? (
              <>
                <div className="w-5 h-5 border-2 border-current border-t-transparent rounded-full animate-spin" />
                <span>Playing...</span>
              </>
            ) : (
              <>
                <Play className="w-5 h-5" />
                <span>Bet ${betAmount.toFixed(2)}</span>
              </>
            )}
          </div>
        </motion.button>
      )}

      {/* Auto bet toggle */}
      {showAutoBet && onAutoStart && !isPlaying && !autoActive && (
        <div>
          <button
            onClick={() => setShowAutoPanel(!showAutoPanel)}
            className="w-full py-2 text-sm text-gray-500 hover:text-casino-cyan flex items-center justify-center gap-2 transition-colors"
          >
            <RefreshCw className="w-4 h-4" />
            <span>{showAutoPanel ? 'Hide Auto Bet' : 'Auto Bet'}</span>
          </button>

          {showAutoPanel && (
            <motion.div
              initial={{ height: 0, opacity: 0 }}
              animate={{ height: 'auto', opacity: 1 }}
              exit={{ height: 0, opacity: 0 }}
              className="mt-3 space-y-3 border-t border-casino-border pt-3"
            >
              <div>
                <label className="text-xs text-gray-500 uppercase tracking-wider">
                  Number of Bets
                </label>
                <div className="grid grid-cols-4 gap-2 mt-1">
                  {[10, 25, 50, 100].map(num => (
                    <button
                      key={num}
                      onClick={() => setAutoConfig(c => ({ ...c, numberOfBets: num }))}
                      className={`py-1.5 rounded text-sm font-bold transition-colors ${
                        autoConfig.numberOfBets === num
                          ? 'bg-casino-cyan/20 text-casino-cyan border border-casino-cyan'
                          : 'bg-casino-border text-gray-400 hover:text-white'
                      }`}
                    >
                      {num}
                    </button>
                  ))}
                </div>
              </div>

              <div className="grid grid-cols-2 gap-2">
                <label className="flex items-center gap-2 text-xs text-gray-400 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={autoConfig.stopOnWin}
                    onChange={(e) => setAutoConfig(c => ({ ...c, stopOnWin: e.target.checked }))}
                    className="rounded bg-casino-bg border-casino-border"
                  />
                  Stop on Win
                </label>
                <label className="flex items-center gap-2 text-xs text-gray-400 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={autoConfig.stopOnLoss}
                    onChange={(e) => setAutoConfig(c => ({ ...c, stopOnLoss: e.target.checked }))}
                    className="rounded bg-casino-bg border-casino-border"
                  />
                  Stop on Loss
                </label>
              </div>

              <div className="grid grid-cols-2 gap-2">
                <div>
                  <label className="text-xs text-gray-500">Stop on Profit</label>
                  <input
                    type="number"
                    value={autoConfig.stopOnProfit}
                    onChange={(e) => setAutoConfig(c => ({ ...c, stopOnProfit: e.target.value }))}
                    placeholder="$"
                    className="w-full mt-1 bg-casino-bg border border-casino-border rounded px-2 py-1.5 text-sm"
                  />
                </div>
                <div>
                  <label className="text-xs text-gray-500">Stop on Loss</label>
                  <input
                    type="number"
                    value={autoConfig.stopOnLossAmount}
                    onChange={(e) => setAutoConfig(c => ({ ...c, stopOnLossAmount: e.target.value }))}
                    placeholder="$"
                    className="w-full mt-1 bg-casino-bg border border-casino-border rounded px-2 py-1.5 text-sm"
                  />
                </div>
              </div>

              <button
                onClick={handleAutoStart}
                disabled={!canBet}
                className="w-full py-3 rounded-lg bg-casino-purple text-white font-bold uppercase text-sm disabled:opacity-50"
              >
                Start Auto Bet
              </button>
            </motion.div>
          )}
        </div>
      )}
    </div>
  );
};

const QuickButton = ({ children, onClick, disabled }) => (
  <button
    onClick={onClick}
    disabled={disabled}
    className="px-3 py-3 bg-casino-border hover:bg-white/10 rounded-lg font-bold text-sm transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
  >
    {children}
  </button>
);

export default BetControls;
