import { motion } from 'framer-motion';
import { useCallback, useRef, useState } from 'react';
import BetControls from '../components/BetControls';
import { useCasino } from '../context/CasinoContext';
import { playSound } from '../utils/audioEngine';

const getRandomFloat = () => {
  const array = new Uint32Array(1);
  crypto.getRandomValues(array);
  return array[0] / (0xFFFFFFFF + 1);
};

const LimboGame = () => {
  const { state, addBalance, subtractBalance } = useCasino();
  const balance = state.balance;
  const soundEnabled = state.settings?.soundEnabled;

  const [betAmount, setBetAmount] = useState(10);
  const [targetMultiplier, setTargetMultiplier] = useState(2);
  const [playing, setPlaying] = useState(false);
  const [result, setResult] = useState(null);
  const [displayMultiplier, setDisplayMultiplier] = useState(1);
  const [history, setHistory] = useState([]);

  // Auto-bet state
  const [autoActive, setAutoActive] = useState(false);
  const [autoBetsRemaining, setAutoBetsRemaining] = useState(0);
  const autoTimeoutRef = useRef(null);
  const autoSettingsRef = useRef({});

  const winChance = Math.min(99, (99 / targetMultiplier)).toFixed(2);
  const potentialWin = (betAmount * targetMultiplier).toFixed(2);

  const play = useCallback((bet = betAmount) => {
    if (bet > balance || playing) return Promise.resolve();

    subtractBalance(bet);
    setPlaying(true);
    setResult(null);
    if (soundEnabled) playSound('betPlace');

    return new Promise((resolve) => {
      // Generate result - house edge means outcomes cluster around 1x
      const random = getRandomFloat();
      // Using crypto-based formula for limbo
      const outcomeMultiplier = Math.max(1, 0.99 / random);

      // Animate
      let current = 1;
      const target = Math.min(outcomeMultiplier, targetMultiplier + 5);
      const duration = 1000;
      const startTime = Date.now();

      const animate = () => {
        const elapsed = Date.now() - startTime;
        const progress = Math.min(elapsed / duration, 1);

        // Ease out animation
        const eased = 1 - Math.pow(1 - progress, 3);
        current = 1 + (target - 1) * eased;

        setDisplayMultiplier(current.toFixed(2));

        if (progress < 1) {
          requestAnimationFrame(animate);
        } else {
          setDisplayMultiplier(outcomeMultiplier.toFixed(2));

          const won = outcomeMultiplier >= targetMultiplier;

          if (won) {
            const winAmount = bet * targetMultiplier;
            addBalance(winAmount);
            setResult({ won: true, multiplier: outcomeMultiplier.toFixed(2), amount: winAmount });
            if (soundEnabled) {
              if (outcomeMultiplier >= 5) playSound('bigWin');
              else playSound('betWin');
            }
          } else {
            setResult({ won: false, multiplier: outcomeMultiplier.toFixed(2), amount: 0 });
            if (soundEnabled) playSound('betLose');
          }

          setHistory(prev => [{
            multiplier: outcomeMultiplier.toFixed(2),
            target: targetMultiplier,
            won
          }, ...prev.slice(0, 19)]);

          setPlaying(false);
          resolve({ won });
        }
      };

      requestAnimationFrame(animate);
    });
  }, [betAmount, balance, playing, subtractBalance, targetMultiplier, addBalance, soundEnabled]);

  const handleAutoStart = useCallback((settings) => {
    autoSettingsRef.current = settings;
    setAutoActive(true);
    setAutoBetsRemaining(settings.numberOfBets === Infinity ? -1 : settings.numberOfBets);

    const runAutoBet = async () => {
      const settings = autoSettingsRef.current;

      if (betAmount > balance) {
        setAutoActive(false);
        setAutoBetsRemaining(0);
        return;
      }

      const res = await play(betAmount);

      setAutoBetsRemaining(prev => {
        if (prev === -1) return -1;
        return prev - 1;
      });

      // Check stop conditions
      if (settings.stopOnWin && res?.won) {
        setAutoActive(false);
        setAutoBetsRemaining(0);
        return;
      }
      if (settings.stopOnLoss && !res?.won) {
        setAutoActive(false);
        setAutoBetsRemaining(0);
        return;
      }

      // Continue auto betting
      autoTimeoutRef.current = setTimeout(() => {
        setAutoBetsRemaining(prev => {
          if (prev === 0) {
            setAutoActive(false);
            return 0;
          }
          runAutoBet();
          return prev;
        });
      }, 1500);
    };

    runAutoBet();
  }, [betAmount, balance, play]);

  const handleAutoStop = useCallback(() => {
    setAutoActive(false);
    setAutoBetsRemaining(0);
    if (autoTimeoutRef.current) {
      clearTimeout(autoTimeoutRef.current);
    }
  }, []);

  return (
    <div className="h-full flex flex-col lg:flex-row gap-4">
      <div className="flex-1 flex flex-col">
        {/* Main display */}
        <div className="flex-1 bg-casino-card border border-casino-border rounded-xl p-6 flex flex-col items-center justify-center">

          {/* Multiplier display */}
          <motion.div
            key={displayMultiplier}
            animate={playing ? { scale: [1, 1.02, 1] } : {}}
            transition={{ duration: 0.05 }}
            className={`text-8xl md:text-9xl font-black mb-4 ${
              result
                ? (result.won ? 'text-casino-green' : 'text-casino-red')
                : (parseFloat(displayMultiplier) >= targetMultiplier ? 'text-casino-green' : 'text-white')
            }`}
          >
            {displayMultiplier}x
          </motion.div>

          {/* Target indicator */}
          <div className="flex items-center gap-4 mb-8">
            <div className={`w-3 h-3 rounded-full ${parseFloat(displayMultiplier) >= targetMultiplier ? 'bg-casino-green' : 'bg-gray-600'}`} />
            <span className="text-gray-400">Target: {targetMultiplier}x</span>
            <div className={`w-3 h-3 rounded-full ${parseFloat(displayMultiplier) >= targetMultiplier ? 'bg-casino-green' : 'bg-gray-600'}`} />
          </div>

          {/* Result message */}
          {result && (
            <motion.div
              initial={{ scale: 0 }}
              animate={{ scale: 1 }}
              className={`px-6 py-3 rounded-xl text-xl font-bold ${
                result.won ? 'bg-casino-green/20 text-casino-green' : 'bg-casino-red/20 text-casino-red'
              }`}
            >
              {result.won ? `WIN! +$${result.amount.toFixed(2)}` : 'BUST'}
            </motion.div>
          )}

          {/* Target multiplier input */}
          <div className="w-full max-w-xs mt-8">
            <label className="text-xs text-gray-500 uppercase mb-2 block text-center">Target Multiplier</label>
            <div className="flex items-center gap-2">
              <button
                onClick={() => setTargetMultiplier(Math.max(1.01, targetMultiplier - 0.5))}
                disabled={playing || autoActive}
                className="px-4 py-2 bg-casino-bg rounded-lg text-white font-bold"
              >
                -
              </button>
              <input
                type="number"
                value={targetMultiplier}
                onChange={(e) => setTargetMultiplier(Math.max(1.01, parseFloat(e.target.value) || 1.01))}
                disabled={playing || autoActive}
                step={0.1}
                min={1.01}
                className="flex-1 bg-casino-bg border border-casino-border rounded-lg px-4 py-2 text-center text-white font-bold text-xl"
              />
              <button
                onClick={() => setTargetMultiplier(targetMultiplier + 0.5)}
                disabled={playing || autoActive}
                className="px-4 py-2 bg-casino-bg rounded-lg text-white font-bold"
              >
                +
              </button>
            </div>
          </div>

          {/* Quick select */}
          <div className="flex gap-2 mt-4">
            {[1.5, 2, 3, 5, 10].map(mult => (
              <button
                key={mult}
                onClick={() => setTargetMultiplier(mult)}
                disabled={playing || autoActive}
                className={`px-3 py-1 rounded text-sm font-bold transition ${
                  targetMultiplier === mult
                    ? 'bg-casino-cyan text-casino-bg'
                    : 'bg-casino-bg text-gray-400 hover:text-white'
                }`}
              >
                {mult}x
              </button>
            ))}
          </div>
        </div>

        {/* History */}
        <div className="flex gap-2 mt-4 overflow-x-auto pb-2">
          {history.map((h, i) => (
            <motion.div
              key={i}
              initial={{ scale: 0 }}
              animate={{ scale: 1 }}
              className={`shrink-0 px-3 py-1.5 rounded text-xs font-bold ${
                h.won ? 'bg-casino-green/20 text-casino-green' : 'bg-casino-red/20 text-casino-red'
              }`}
            >
              {h.multiplier}x
            </motion.div>
          ))}
        </div>
      </div>

      <div className="w-full lg:w-80 space-y-4">
        <BetControls
          betAmount={betAmount}
          onBetChange={setBetAmount}
          onBet={() => play()}
          balance={balance}
          disabled={playing || autoActive}
          buttonText={playing ? "PLAYING..." : "PLAY"}
          showAutoBet={true}
          autoActive={autoActive}
          autoBetsRemaining={autoBetsRemaining}
          onAutoStart={handleAutoStart}
          onAutoStop={handleAutoStop}
        />

        <div className="bg-casino-card border border-casino-border rounded-xl p-4 space-y-3">
          <div className="flex justify-between items-center">
            <span className="text-xs text-gray-500 uppercase">Win Chance</span>
            <span className="text-lg font-bold text-casino-cyan">{winChance}%</span>
          </div>
          <div className="flex justify-between items-center">
            <span className="text-xs text-gray-500 uppercase">Potential Win</span>
            <span className="text-lg font-bold text-casino-green">${potentialWin}</span>
          </div>
        </div>

        <div className="bg-casino-card border border-casino-border rounded-xl p-4">
          <p className="text-xs text-gray-500 leading-relaxed">
            Set a target multiplier and hope the random outcome reaches it. Higher targets = higher payouts but lower chances.
          </p>
        </div>
      </div>
    </div>
  );
};

export default LimboGame;
