import { AnimatePresence, motion } from 'framer-motion';
import { Info, Rocket, TrendingUp, Zap } from 'lucide-react';
import { useCallback, useEffect, useRef, useState } from 'react';
import BetControls from '../components/BetControls';
import { useCasino } from '../context/CasinoContext';
import { playSound } from '../utils/audioEngine';

const getRandomFloat = () => {
  const array = new Uint32Array(1);
  crypto.getRandomValues(array);
  return array[0] / (0xffffffff + 1);
};

const generateCrashPoint = () => {
  const e = getRandomFloat();
  if (e < 0.01) return 1.0;
  const houseEdge = 0.99;
  const crashPoint = houseEdge / e;
  return Math.min(1000, Math.max(1.0, Math.floor(crashPoint * 100) / 100));
};

const CrashGame = () => {
  const { state, addBalance, subtractBalance } = useCasino();
  const balance = state.balance;
  const soundEnabled = state.settings?.soundEnabled;

  const [betAmount, setBetAmount] = useState(10);
  const [gamePhase, setGamePhase] = useState('waiting');
  const [currentMultiplier, setCurrentMultiplier] = useState(1.0);
  const [crashPoint, setCrashPoint] = useState(null);
  const [autoCashout, setAutoCashout] = useState(2.0);
  const [autoCashoutEnabled, setAutoCashoutEnabled] = useState(false);
  const [autoBetEnabled, setAutoBetEnabled] = useState(false);
  const [hasBet, setHasBet] = useState(false);
  const [hasCashedOut, setHasCashedOut] = useState(false);
  const [cashoutMultiplier, setCashoutMultiplier] = useState(null);
  const [countdown, setCountdown] = useState(0);
  const [history, setHistory] = useState([]);

  const canvasRef = useRef(null);
  const animationRef = useRef(null);
  const startTimeRef = useRef(null);
  const crashPointRef = useRef(null);
  const gamePhaseRef = useRef('waiting');
  const hasCashedOutRef = useRef(false);
  const hasBetRef = useRef(false);
  const currentMultiplierRef = useRef(1.0);
  const autoCashoutRef = useRef({ enabled: false, value: 2.0 });
  const autoBetRef = useRef(false);
  const betAmountRef = useRef(10);

  useEffect(() => {
    gamePhaseRef.current = gamePhase;
  }, [gamePhase]);

  useEffect(() => {
    hasCashedOutRef.current = hasCashedOut;
  }, [hasCashedOut]);

  useEffect(() => {
    hasBetRef.current = hasBet;
  }, [hasBet]);

  useEffect(() => {
    autoCashoutRef.current = { enabled: autoCashoutEnabled, value: autoCashout };
  }, [autoCashoutEnabled, autoCashout]);

  useEffect(() => {
    autoBetRef.current = autoBetEnabled;
  }, [autoBetEnabled]);

  useEffect(() => {
    betAmountRef.current = betAmount;
  }, [betAmount]);

  const drawGraph = useCallback((multiplier, crashed = false) => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    const rect = canvas.getBoundingClientRect();
    const dpr = window.devicePixelRatio || 1;

    if (canvas.width !== rect.width * dpr || canvas.height !== rect.height * dpr) {
      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;
      ctx.scale(dpr, dpr);
    }

    const width = rect.width;
    const height = rect.height;

    ctx.clearRect(0, 0, width, height);
    ctx.fillStyle = '#0a0a0a';
    ctx.fillRect(0, 0, width, height);

    ctx.strokeStyle = '#1a1a1a';
    ctx.lineWidth = 1;
    for (let i = 1; i < 10; i++) {
      const y = (height / 10) * i;
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(width, y);
      ctx.stroke();
      const x = (width / 10) * i;
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, height);
      ctx.stroke();
    }

    const points = [];
    const maxMult = Math.max(multiplier, 2);
    const timeScale = Math.log(maxMult) / Math.log(1.06);

    for (let t = 0; t <= 100; t += 1) {
      const m = Math.pow(1.06, (t * timeScale) / 100);
      if (m > multiplier) break;
      const x = (t / 100) * width * 0.9 + width * 0.05;
      const y = height - ((m - 1) / (maxMult - 1)) * height * 0.85 - height * 0.1;
      points.push({ x, y });
    }

    if (points.length > 1) {
      ctx.beginPath();
      ctx.moveTo(points[0].x, points[0].y);
      for (let i = 1; i < points.length; i++) {
        ctx.lineTo(points[i].x, points[i].y);
      }

      const gradient = ctx.createLinearGradient(0, height, 0, 0);
      if (crashed) {
        gradient.addColorStop(0, '#ef4444');
        gradient.addColorStop(1, '#dc2626');
      } else {
        gradient.addColorStop(0, '#22c55e');
        gradient.addColorStop(1, '#4ade80');
      }
      ctx.strokeStyle = gradient;
      ctx.lineWidth = 3;
      ctx.lineCap = 'round';
      ctx.stroke();

      ctx.lineTo(points[points.length - 1].x, height);
      ctx.lineTo(points[0].x, height);
      ctx.closePath();
      ctx.fillStyle = gradient;
      ctx.globalAlpha = 0.1;
      ctx.fill();
      ctx.globalAlpha = 1;
    }
  }, []);

  const doCashOut = useCallback(() => {
    if (!hasBetRef.current || hasCashedOutRef.current || gamePhaseRef.current !== 'running') return;

    const mult = currentMultiplierRef.current;
    const winnings = betAmount * mult;

    setHasCashedOut(true);
    hasCashedOutRef.current = true;
    setCashoutMultiplier(mult);
    addBalance(winnings);

    if (soundEnabled) {
      playSound('cashout');
      if (mult >= 5) playSound('bigWin');
      else playSound('betWin');
    }
  }, [betAmount, addBalance, soundEnabled]);

  const runGame = useCallback(() => {
    if (gamePhaseRef.current !== 'running') return;

    const elapsed = (performance.now() - startTimeRef.current) / 1000;
    const newMultiplier = Math.pow(1.06, elapsed * 8);
    const cappedMultiplier = Math.min(newMultiplier, 1000);
    const displayMult = Math.floor(cappedMultiplier * 100) / 100;

    currentMultiplierRef.current = displayMult;
    setCurrentMultiplier(displayMult);

    const ac = autoCashoutRef.current;
    if (ac.enabled && hasBetRef.current && !hasCashedOutRef.current && displayMult >= ac.value) {
      doCashOut();
    }

    if (displayMult >= crashPointRef.current) {
      setGamePhase('crashed');
      gamePhaseRef.current = 'crashed';
      setCurrentMultiplier(crashPointRef.current);
      drawGraph(crashPointRef.current, true);
      setHistory((prev) => [crashPointRef.current, ...prev.slice(0, 14)]);

      setTimeout(() => {
        startBettingPhase();
      }, 3000);
      return;
    }

    drawGraph(displayMult, false);
    animationRef.current = requestAnimationFrame(runGame);
  }, [doCashOut, drawGraph]);

  const startBettingPhase = useCallback(() => {
    setGamePhase('betting');
    gamePhaseRef.current = 'betting';
    setCurrentMultiplier(1.0);
    currentMultiplierRef.current = 1.0;
    setCrashPoint(null);
    setHasBet(false);
    hasBetRef.current = false;
    setHasCashedOut(false);
    hasCashedOutRef.current = false;
    setCashoutMultiplier(null);
    crashPointRef.current = null;

    // Auto-bet: place bet at start of betting phase
    if (autoBetRef.current && betAmountRef.current <= balance) {
      setTimeout(() => {
        if (autoBetRef.current && gamePhaseRef.current === 'betting' && !hasBetRef.current) {
          subtractBalance(betAmountRef.current);
          setHasBet(true);
          hasBetRef.current = true;
          if (soundEnabled) playSound('betPlace');
        }
      }, 500);
    }

    let count = 5;
    setCountdown(count);

    const countdownInterval = setInterval(() => {
      count--;
      setCountdown(count);

      if (count <= 0) {
        clearInterval(countdownInterval);
        startRunningPhase();
      }
    }, 1000);
  }, [balance, subtractBalance, soundEnabled]);

  const startRunningPhase = useCallback(() => {
    const newCrashPoint = generateCrashPoint();
    setCrashPoint(newCrashPoint);
    crashPointRef.current = newCrashPoint;
    startTimeRef.current = performance.now();

    setGamePhase('running');
    gamePhaseRef.current = 'running';

    animationRef.current = requestAnimationFrame(runGame);
  }, [runGame]);

  const placeBet = useCallback(() => {
    if (gamePhaseRef.current !== 'betting' || betAmountRef.current > balance || hasBetRef.current) return;

    subtractBalance(betAmountRef.current);
    setHasBet(true);
    hasBetRef.current = true;
    setHasCashedOut(false);
    hasCashedOutRef.current = false;
    if (soundEnabled) playSound('betPlace');
  }, [balance, subtractBalance, soundEnabled]);

  useEffect(() => {
    drawGraph(1.0, false);
    startBettingPhase();

    return () => {
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
      }
    };
  }, []);

  const getMultiplierColor = () => {
    if (gamePhase === 'crashed') return 'text-casino-red';
    if (currentMultiplier >= 5) return 'text-casino-gold';
    if (currentMultiplier >= 2) return 'text-casino-green';
    return 'text-white';
  };

  const getButtonText = () => {
    if (gamePhase === 'betting') {
      if (hasBet) return 'BET PLACED ✓';
      return countdown > 0 ? `BET NOW (${countdown}s)` : 'PLACE BET';
    }
    if (gamePhase === 'running') {
      if (!hasBet) return 'NO BET';
      if (hasCashedOut) return 'CASHED OUT ✓';
      return `CASH OUT $${(betAmount * currentMultiplier).toFixed(2)}`;
    }
    if (gamePhase === 'crashed') return 'NEXT ROUND...';
    return 'WAITING...';
  };

  const isButtonDisabled = () => {
    if (gamePhase === 'betting') return hasBet || betAmount > balance;
    if (gamePhase === 'running') return !hasBet || hasCashedOut;
    return true;
  };

  const handleButtonClick = () => {
    if (gamePhase === 'betting' && !hasBet) {
      placeBet();
    } else if (gamePhase === 'running' && hasBet && !hasCashedOut) {
      doCashOut();
    }
  };

  return (
    <div className="h-full flex flex-col lg:flex-row gap-4">
      <div className="flex-1 flex flex-col min-h-0">
        <div className="flex-1 bg-gradient-to-b from-casino-card via-casino-bg to-casino-card border border-casino-border rounded-xl p-4 relative overflow-hidden min-h-[400px]">
          <canvas ref={canvasRef} className="w-full h-full absolute inset-0" />

          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 text-center z-10">
            <AnimatePresence mode="wait">
              {gamePhase === 'betting' && (
                <motion.div
                  key="betting"
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  exit={{ opacity: 0 }}
                  className="text-center"
                >
                  <div className="text-2xl text-gray-400 mb-2">PLACE YOUR BETS</div>
                  <div className="text-6xl font-black text-casino-cyan">{countdown}s</div>
                </motion.div>
              )}

              {gamePhase === 'running' && (
                <motion.div key="running" initial={{ scale: 0.9 }} animate={{ scale: 1 }} className="flex flex-col items-center">
                  <Rocket className={`w-12 h-12 mb-2 ${getMultiplierColor()}`} />
                  <div className={`text-7xl font-black ${getMultiplierColor()}`}>{currentMultiplier.toFixed(2)}x</div>
                </motion.div>
              )}

              {gamePhase === 'crashed' && (
                <motion.div key="crashed" initial={{ scale: 1.5 }} animate={{ scale: 1 }} className="flex flex-col items-center">
                  <div className="text-casino-red text-6xl font-black">CRASHED</div>
                  <div className="text-white text-3xl font-bold mt-2">@ {crashPoint?.toFixed(2)}x</div>
                </motion.div>
              )}
            </AnimatePresence>
          </div>

          <AnimatePresence>
            {hasCashedOut && cashoutMultiplier && (
              <motion.div
                initial={{ y: 50, opacity: 0 }}
                animate={{ y: 0, opacity: 1 }}
                exit={{ y: -50, opacity: 0 }}
                className="absolute bottom-6 left-1/2 -translate-x-1/2 bg-casino-green px-8 py-4 rounded-xl z-20"
              >
                <div className="text-casino-bg font-black text-2xl">CASHED OUT @ {cashoutMultiplier.toFixed(2)}x</div>
                <div className="text-casino-bg/80 text-center font-bold text-lg">+${(betAmount * cashoutMultiplier).toFixed(2)}</div>
              </motion.div>
            )}
          </AnimatePresence>

          <div className="absolute top-4 left-4 flex gap-2 flex-wrap max-w-xs z-10">
            {history.map((h, i) => (
              <span
                key={`${h}-${i}`}
                className={`text-xs font-bold px-2 py-1 rounded ${h < 2 ? 'bg-casino-red/20 text-casino-red' : 'bg-casino-green/20 text-casino-green'}`}
              >
                {h.toFixed(2)}x
              </span>
            ))}
          </div>
        </div>
      </div>

      <div className="w-full lg:w-80 flex flex-col gap-3">
        <BetControls
          betAmount={betAmount}
          onBetChange={setBetAmount}
          onBet={handleButtonClick}
          balance={balance}
          disabled={isButtonDisabled()}
          buttonText={getButtonText()}
          buttonClassName={gamePhase === 'running' && hasBet && !hasCashedOut ? 'bg-casino-green text-casino-bg animate-pulse' : ''}
          showAutoBet={false}
        />

        <div className="bg-casino-card border border-casino-border rounded-xl p-4">
          <div className="flex items-center justify-between mb-3">
            <div className="flex items-center gap-2">
              <TrendingUp className="w-4 h-4 text-casino-green" />
              <span className="text-sm font-bold uppercase text-gray-400">Auto Bet</span>
            </div>
            <button
              onClick={() => setAutoBetEnabled(!autoBetEnabled)}
              className={`w-12 h-6 rounded-full transition-colors relative ${autoBetEnabled ? 'bg-casino-green' : 'bg-casino-border'}`}
            >
              <div className={`absolute top-0.5 w-5 h-5 rounded-full bg-white transition-all ${autoBetEnabled ? 'left-6' : 'left-0.5'}`} />
            </button>
          </div>
          <p className="text-xs text-gray-500">Automatically place bet at start of each round</p>
        </div>

        <div className="bg-casino-card border border-casino-border rounded-xl p-4">
          <div className="flex items-center justify-between mb-3">
            <div className="flex items-center gap-2">
              <Zap className="w-4 h-4 text-casino-cyan" />
              <span className="text-sm font-bold uppercase text-gray-400">Auto Cashout</span>
            </div>
            <button
              onClick={() => setAutoCashoutEnabled(!autoCashoutEnabled)}
              className={`w-12 h-6 rounded-full transition-colors relative ${autoCashoutEnabled ? 'bg-casino-green' : 'bg-casino-border'}`}
            >
              <div className={`absolute top-0.5 w-5 h-5 rounded-full bg-white transition-all ${autoCashoutEnabled ? 'left-6' : 'left-0.5'}`} />
            </button>
          </div>
          <div className="flex gap-2">
            <input
              type="number"
              min="1.01"
              step="0.1"
              value={autoCashout}
              onChange={(e) => setAutoCashout(Math.max(1.01, parseFloat(e.target.value) || 1.01))}
              className="flex-1 bg-casino-bg border border-casino-border rounded-lg px-3 py-2 text-white font-mono"
            />
            <span className="flex items-center text-gray-400 font-bold">x</span>
          </div>
        </div>

        <div className="bg-casino-card border border-casino-border rounded-xl p-4">
          <div className="flex items-center gap-2 mb-3">
            <TrendingUp className="w-4 h-4 text-casino-gold" />
            <span className="text-xs font-bold uppercase tracking-wider text-gray-400">Quick Targets</span>
          </div>
          <div className="grid grid-cols-4 gap-2">
            {[1.5, 2, 3, 5].map((mult) => (
              <button
                key={mult}
                onClick={() => {
                  setAutoCashout(mult);
                  setAutoCashoutEnabled(true);
                }}
                className="py-2 bg-casino-border hover:bg-casino-cyan/30 rounded-lg text-sm font-bold transition-colors"
              >
                {mult}x
              </button>
            ))}
          </div>
        </div>

        <div className="bg-casino-card border border-casino-border rounded-xl p-4">
          <div className="flex items-center gap-2 mb-2">
            <Info className="w-4 h-4 text-casino-cyan" />
            <span className="text-xs font-bold uppercase tracking-wider text-gray-400">About</span>
          </div>
          <p className="text-xs text-gray-500 leading-relaxed">
            Place your bet during the countdown. Cash out before it crashes! The longer you wait, the higher the multiplier but also the risk.
          </p>
        </div>
      </div>
    </div>
  );
};

export default CrashGame;
