import { motion } from 'framer-motion';
import {
    BarChart3, DollarSign,
    Flame,
    Percent,
    Target,
    TrendingDown,
    TrendingUp,
    Trophy,
    X,
    Zap
} from 'lucide-react';
import { useCasino } from '../../context/CasinoContext';

const StatsModal = ({ onClose }) => {
  const { state } = useCasino();
  const { stats, betHistory } = state;

  // Get game-specific stats
  const gameStats = betHistory.reduce((acc, bet) => {
    if (!acc[bet.game]) {
      acc[bet.game] = { bets: 0, wagered: 0, won: 0, wins: 0 };
    }
    acc[bet.game].bets++;
    acc[bet.game].wagered += bet.amount;
    if (bet.win) {
      acc[bet.game].wins++;
      acc[bet.game].won += bet.payout;
    }
    return acc;
  }, {});

  // Get recent history (last 10)
  const recentHistory = betHistory.slice(-10).reverse();

  return (
    <div className="bg-casino-card border border-casino-border rounded-2xl overflow-hidden max-h-[80vh] overflow-y-auto">
      {/* Header */}
      <div className="flex items-center justify-between p-6 border-b border-casino-border sticky top-0 bg-casino-card z-10">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-lg bg-casino-cyan/20 border border-casino-cyan flex items-center justify-center">
            <BarChart3 className="w-5 h-5 text-casino-cyan" />
          </div>
          <div>
            <h2 className="font-display font-bold text-xl">Statistics</h2>
            <p className="text-xs text-gray-500">Your gaming analytics</p>
          </div>
        </div>
        <button
          onClick={onClose}
          className="p-2 rounded-lg hover:bg-white/10 transition-colors"
        >
          <X className="w-5 h-5" />
        </button>
      </div>

      {/* Content */}
      <div className="p-6 space-y-6">
        {/* Main stats grid */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          <StatCard
            icon={Target}
            label="Total Bets"
            value={stats.totalBets.toString()}
            color="cyan"
          />
          <StatCard
            icon={DollarSign}
            label="Total Wagered"
            value={`$${stats.totalWagered.toFixed(2)}`}
            color="purple"
          />
          <StatCard
            icon={Percent}
            label="Win Rate"
            value={`${stats.winRate.toFixed(1)}%`}
            color="gold"
          />
          <StatCard
            icon={stats.netProfit >= 0 ? TrendingUp : TrendingDown}
            label="Net Profit"
            value={`${stats.netProfit >= 0 ? '+' : ''}$${stats.netProfit.toFixed(2)}`}
            color={stats.netProfit >= 0 ? 'green' : 'red'}
          />
        </div>

        {/* Highlights */}
        <section>
          <h3 className="flex items-center gap-2 text-sm font-bold uppercase tracking-wider text-casino-gold mb-4">
            <Trophy className="w-4 h-4" />
            Highlights
          </h3>

          <div className="grid grid-cols-2 gap-4">
            <div className="bg-casino-bg border border-casino-border rounded-lg p-4">
              <div className="flex items-center gap-2 text-casino-green mb-2">
                <TrendingUp className="w-4 h-4" />
                <span className="text-xs uppercase tracking-wider">Biggest Win</span>
              </div>
              <p className="font-display font-bold text-2xl text-casino-green">
                ${stats.biggestWin.toFixed(2)}
              </p>
            </div>

            <div className="bg-casino-bg border border-casino-border rounded-lg p-4">
              <div className="flex items-center gap-2 text-casino-red mb-2">
                <TrendingDown className="w-4 h-4" />
                <span className="text-xs uppercase tracking-wider">Biggest Loss</span>
              </div>
              <p className="font-display font-bold text-2xl text-casino-red">
                ${stats.biggestLoss.toFixed(2)}
              </p>
            </div>

            <div className="bg-casino-bg border border-casino-border rounded-lg p-4 col-span-2">
              <div className="flex items-center gap-2 text-casino-cyan mb-2">
                <Flame className="w-4 h-4" />
                <span className="text-xs uppercase tracking-wider">Current Streak</span>
              </div>
              <p className={`font-display font-bold text-2xl ${
                stats.currentStreak > 0 ? 'text-casino-green' :
                stats.currentStreak < 0 ? 'text-casino-red' : 'text-gray-500'
              }`}>
                {stats.currentStreak > 0 ? `${stats.currentStreak} Wins` :
                 stats.currentStreak < 0 ? `${Math.abs(stats.currentStreak)} Losses` :
                 'No streak'}
              </p>
            </div>
          </div>
        </section>

        {/* Game breakdown */}
        {Object.keys(gameStats).length > 0 && (
          <section>
            <h3 className="flex items-center gap-2 text-sm font-bold uppercase tracking-wider text-casino-purple mb-4">
              <Zap className="w-4 h-4" />
              By Game
            </h3>

            <div className="space-y-3">
              {Object.entries(gameStats).map(([game, data]) => {
                const winRate = data.bets > 0 ? (data.wins / data.bets) * 100 : 0;
                const profit = data.won - data.wagered;

                return (
                  <div
                    key={game}
                    className="bg-casino-bg border border-casino-border rounded-lg p-4"
                  >
                    <div className="flex items-center justify-between mb-2">
                      <h4 className="font-medium capitalize">{game}</h4>
                      <span className={`text-sm font-mono ${
                        profit >= 0 ? 'text-casino-green' : 'text-casino-red'
                      }`}>
                        {profit >= 0 ? '+' : ''}${profit.toFixed(2)}
                      </span>
                    </div>

                    <div className="flex items-center gap-4 text-xs text-gray-400">
                      <span>{data.bets} bets</span>
                      <span>{winRate.toFixed(1)}% win rate</span>
                      <span>${data.wagered.toFixed(2)} wagered</span>
                    </div>

                    {/* Progress bar */}
                    <div className="mt-2 h-1 bg-casino-border rounded-full overflow-hidden">
                      <motion.div
                        className="h-full bg-gradient-to-r from-casino-cyan to-casino-purple"
                        initial={{ width: 0 }}
                        animate={{ width: `${winRate}%` }}
                        transition={{ duration: 0.5 }}
                      />
                    </div>
                  </div>
                );
              })}
            </div>
          </section>
        )}

        {/* Recent history */}
        {recentHistory.length > 0 && (
          <section>
            <h3 className="flex items-center gap-2 text-sm font-bold uppercase tracking-wider text-casino-cyan mb-4">
              <BarChart3 className="w-4 h-4" />
              Recent Bets
            </h3>

            <div className="space-y-2">
              {recentHistory.map((bet, index) => (
                <motion.div
                  key={bet.timestamp}
                  initial={{ opacity: 0, x: -20 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ delay: index * 0.05 }}
                  className="flex items-center justify-between bg-casino-bg border border-casino-border rounded-lg px-4 py-3"
                >
                  <div className="flex items-center gap-3">
                    <div className={`w-2 h-2 rounded-full ${
                      bet.win ? 'bg-casino-green' : 'bg-casino-red'
                    }`} />
                    <span className="capitalize text-sm">{bet.game}</span>
                  </div>

                  <div className="flex items-center gap-4">
                    <span className="text-sm text-gray-400">
                      ${bet.amount.toFixed(2)}
                    </span>
                    <span className="text-xs text-gray-500">
                      {bet.multiplier?.toFixed(2)}x
                    </span>
                    <span className={`text-sm font-mono font-bold ${
                      bet.win ? 'text-casino-green' : 'text-casino-red'
                    }`}>
                      {bet.win ? `+$${(bet.payout - bet.amount).toFixed(2)}` : `-$${bet.amount.toFixed(2)}`}
                    </span>
                  </div>
                </motion.div>
              ))}
            </div>
          </section>
        )}

        {/* Empty state */}
        {stats.totalBets === 0 && (
          <div className="text-center py-12">
            <BarChart3 className="w-12 h-12 text-gray-600 mx-auto mb-4" />
            <p className="text-gray-400">No bets yet</p>
            <p className="text-sm text-gray-600">Start playing to see your statistics!</p>
          </div>
        )}
      </div>
    </div>
  );
};

// Stat Card Component
const StatCard = ({ icon: Icon, label, value, color }) => {
  const colorClasses = {
    cyan: 'text-casino-cyan border-casino-cyan/30',
    purple: 'text-casino-purple border-casino-purple/30',
    gold: 'text-casino-gold border-casino-gold/30',
    green: 'text-casino-green border-casino-green/30',
    red: 'text-casino-red border-casino-red/30'
  };

  return (
    <div className={`bg-casino-bg border rounded-lg p-4 ${colorClasses[color]}`}>
      <div className="flex items-center gap-2 mb-2">
        <Icon className="w-4 h-4 opacity-60" />
        <span className="text-xs text-gray-500 uppercase tracking-wider">{label}</span>
      </div>
      <p className="font-display font-bold text-xl">{value}</p>
    </div>
  );
};

export default StatsModal;
